def _seg(value: str) -> str:
    """One path segment. A value containing `/`, `?` or `#` would address another route, so it is refused here
    rather than spliced in (httpx would normalise `%2F` back to `/`)."""
    text = str(value)
    if text == "" or any(c in text for c in "/?#"):
        raise GraphOWLError(f"`{text}` cannot be used as a path segment")
    return text


